import{_ as o,o as t,c as s,a3 as a}from"./chunks/framework.Bu2zoybE.js";const m=JSON.parse('{"title":"Mockups are stories in the component workshop","description":"","frontmatter":{"status":"accepted","date":"2026-11-14T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0029-mockups-are-stories-in-the-component-workshop.md","filePath":"docs/adr/0029-mockups-are-stories-in-the-component-workshop.md"}'),n={name:"docs/adr/0029-mockups-are-stories-in-the-component-workshop.md"};function r(i,e,c,h,d,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="mockups-are-stories-in-the-component-workshop" tabindex="-1">Mockups are stories in the component workshop <a class="header-anchor" href="#mockups-are-stories-in-the-component-workshop" aria-label="Permalink to &quot;Mockups are stories in the component workshop&quot;">​</a></h1><p>Screen mockups are stories in the Storybook workshop (<a href="./0028-storybook-is-the-component-workshop-of-the-design-system">ADR 0028</a>), and the workshop is the home of the whole design system documentation: rules, tokens, components and mockups. This replaces <a href="./0016-mockups-are-plain-html-in-the-repo">ADR 0016</a>, which kept mockups as plain HTML pages under <code>design/mockups/</code>, and amends <a href="./0023-the-websites-share-one-vue-and-daisyui-design-system">ADR 0023</a>, whose web mockups were plain HTML that wrote the components&#39; classes.</p><p>The owner chose this on 14 November 2026, after the workshop showed it can hold written pages, live components and embedded content, and keeping the mockups apart meant describing the same components in two places.</p><h2 id="what-it-means" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means" aria-label="Permalink to &quot;What it means&quot;">​</a></h2><ul><li><strong>Components are the Vue components.</strong> The stories of <code>web/ui</code> are the documentation of each component, its states and the classes it renders.</li><li><strong>A web mockup is a story that composes the Vue components</strong> into a full screen or part of a screen. It draws what the web app will render, because it is built from the same pieces. A component a web mockup needs and <code>web/ui</code> lacks is added to <code>web/ui</code> first, with its stories, as before.</li><li><strong>A phone or tablet mockup is a story drawn with an isolated stylesheet</strong> that reads the shared tokens (<code>--cp-*</code>) and nothing from the Vue components&#39; CSS. It describes the Compose and SwiftUI screens, which DaisyUI&#39;s look does not match, as <code>mockup.css</code> did.</li><li><strong>Draft and agreed are tags on the story</strong>, not folders. A new screen or a redesign is tagged <code>draft</code>. Validating it is a PR that changes the tag to <code>agreed</code> and replaces the agreed story it redesigns; the owner&#39;s merge is the approval. Nothing is built from a <code>draft</code> story. The tag also puts the story in the matching part of the workshop&#39;s sidebar.</li><li><strong>The rules of ADR 0016 carry over</strong>, now as story rules: English only; light and dark from the roles, never a palette step; no network; real elements, a <code>data-component</code> attribute and glossary <code>id</code>s for the regions an issue would name; one story per screen state, with the same name for its phone, tablet and web versions. The workshop&#39;s accessibility check covers every mockup story.</li><li><strong>The agreed mockup is still the contract.</strong> Moving a mockup into a story changes its form, not its content: each converted mockup is compared with the old HTML by screenshot, light and dark, before the old file is deleted, and any difference is listed in the PR.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><ul><li>One place describes the design system: its rules, its components and the screens drawn from them. A reviewer no longer compares a gallery page with a mockup page with a component page.</li><li>A web mockup built from the components cannot drift from them, and a component change shows up in every screen that uses it.</li><li>Stories are checked: accessibility, light and dark, and the interaction a mockup shows.</li><li>Agents reach mockups through the Storybook MCP like any other story.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The migration is staged, in this order: the workshop pages and the tag; the phone and tablet stylesheet; the 41 agreed web mockups; the 124 agreed phone mockups and the draft. Until a mockup is converted, its HTML file stays the contract and ADR 0016&#39;s checks still apply to it.</li><li><code>design/check-mockups.mjs</code>, the docs site&#39;s mockup pages and its &quot;Review in the docs&quot; mockup links are replaced by the story tests and links to the stories as each stage lands.</li><li><code>design/mockups/</code> goes once every mockup is converted. Git history keeps the originals.</li><li>The docs site keeps what is not design system: architecture, decisions, the brand, translations and the roadmap. Its top menu links to the workshop.</li></ul>',9)])])}const u=o(n,[["render",r]]);export{m as __pageData,u as default};
